package backup

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"log"
	"net/http"
	"strconv"
	"strings"
	"time"

	"dylaris-core/handlers/httpx"
	"dylaris-core/models"
	"dylaris-core/services"
	backupstorage "dylaris-core/storage/backup"

	pbNode "dylaris-proto/node"

	"github.com/google/uuid"
	"github.com/gorilla/mux"
)

// The backup storage speed test. A node PUTs generated bytes to a presigned
// URL for a throwaway key and reports how long it took; Core deletes the key
// either way. It measures that node's way to that storage, so the answer names
// the node, and the panel offers it as a hint for the storage's upload cap.
//
// Two doors: an operator tests a platform storage from a platform node, a
// tenant tests their own bucket from a node their servers run on or their own
// machine. Each node runs one test at a time, and each account one every
// speedTestCooldown, because a test fills the node's uplink while it runs.

var speedTestSizesMB = map[int64]bool{64: true, 256: true, 512: true}

const (
	speedTestCooldown = 2 * time.Minute
	// speedTestWait outlasts the node's own 3 minute bound, so its answer -
	// a result or why it gave up - is what the caller sees.
	speedTestWait = 200 * time.Second
)

type speedTestNode struct {
	ID     int    `json:"id"`
	Name   string `json:"name"`
	Online bool   `json:"online"`
}

// SpeedTestNodes GET /api/backup-storages/{id}/speedtest-nodes - the nodes an
// operator may test a platform storage from: the platform's, never a tenant's
// machine (that is their uplink).
func (h *BackupHandler) SpeedTestNodes(w http.ResponseWriter, r *http.Request) {
	if _, ok := h.platformStorage(w, storageIDParam(r)); !ok {
		return
	}
	nodes, err := h.d.Store.ListNodes()
	if err != nil {
		httpx.SendJSONError(w, "Failed to list nodes", http.StatusInternalServerError)
		return
	}
	var out []models.Node
	for _, n := range nodes {
		if n.OwnerID == nil {
			out = append(out, n)
		}
	}
	h.writeSpeedTestNodes(w, out)
}

// SpeedTestStorage POST /api/backup-storages/{id}/speedtest
func (h *BackupHandler) SpeedTestStorage(w http.ResponseWriter, r *http.Request) {
	bs, ok := h.platformStorage(w, storageIDParam(r))
	if !ok {
		return
	}
	h.speedTest(w, r, bs, func(n *models.Node) bool { return n.OwnerID == nil })
}

// SpeedTestOwnNodes GET /api/me/backup-storages/{id}/speedtest-nodes
func (h *BackupHandler) SpeedTestOwnNodes(w http.ResponseWriter, r *http.Request) {
	if _, ok := h.ownStorageFor(w, r); !ok {
		return
	}
	nodes, err := h.tenantTestNodes(r)
	if err != nil {
		httpx.SendJSONError(w, "Failed to list nodes", http.StatusInternalServerError)
		return
	}
	h.writeSpeedTestNodes(w, nodes)
}

// SpeedTestOwnStorage POST /api/me/backup-storages/{id}/speedtest
func (h *BackupHandler) SpeedTestOwnStorage(w http.ResponseWriter, r *http.Request) {
	bs, ok := h.ownStorageFor(w, r)
	if !ok {
		return
	}
	allowed, err := h.tenantTestNodes(r)
	if err != nil {
		httpx.SendJSONError(w, "Failed to list nodes", http.StatusInternalServerError)
		return
	}
	h.speedTest(w, r, bs, func(n *models.Node) bool {
		for _, a := range allowed {
			if a.ID == n.ID {
				return true
			}
		}
		return false
	})
}

// tenantTestNodes is where a tenant's backups actually leave from: the nodes
// their servers run on, and their own machines.
func (h *BackupHandler) tenantTestNodes(r *http.Request) ([]models.Node, error) {
	userID, _ := r.Context().Value("userID").(string)
	seen := map[int]bool{}
	var out []models.Node
	own, err := h.d.Store.ListNodesByOwner(userID)
	if err != nil {
		return nil, err
	}
	for _, n := range own {
		seen[n.ID] = true
		out = append(out, n)
	}
	servers, err := h.d.Store.ListServersByOwner(userID)
	if err != nil {
		return nil, err
	}
	for _, s := range servers {
		if s.NodeID == 0 || seen[s.NodeID] {
			continue
		}
		seen[s.NodeID] = true
		if n, err := h.d.Store.GetNodeByID(s.NodeID); err == nil && n != nil {
			out = append(out, *n)
		}
	}
	return out, nil
}

func (h *BackupHandler) writeSpeedTestNodes(w http.ResponseWriter, nodes []models.Node) {
	out := make([]speedTestNode, 0, len(nodes))
	for _, n := range nodes {
		name := n.DisplayName
		if name == "" {
			name = n.Name
		}
		out = append(out, speedTestNode{ID: n.ID, Name: name, Online: h.d.GRPCRegistry != nil && h.d.GRPCRegistry.IsConnected(n.ID)})
	}
	json.NewEncoder(w).Encode(map[string]any{"success": true, "nodes": out})
}

func (h *BackupHandler) speedTest(w http.ResponseWriter, r *http.Request, bs *models.BackupStorage, mayUse func(*models.Node) bool) {
	var req struct {
		NodeID int   `json:"nodeId"`
		SizeMB int64 `json:"sizeMb"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		httpx.SendJSONError(w, "Invalid JSON", http.StatusBadRequest)
		return
	}
	if !speedTestSizesMB[req.SizeMB] {
		httpx.SendJSONError(w, "Test size must be 64, 256 or 512 MB", http.StatusBadRequest)
		return
	}
	node, err := h.d.Store.GetNodeByID(req.NodeID)
	if err != nil || node == nil || !mayUse(node) {
		httpx.SendJSONError(w, "Node not found", http.StatusNotFound)
		return
	}
	if h.d.GRPCRegistry == nil || !h.d.GRPCRegistry.IsConnected(node.ID) {
		httpx.SendJSONError(w, "That node is offline", http.StatusConflict)
		return
	}
	userID, _ := r.Context().Value("userID").(string)
	if h.d.Redis != nil {
		ok, err := h.d.Redis.SetNX(r.Context(), "dylaris:speedtest:user:"+userID, "1", speedTestCooldown).Result()
		if err == nil && !ok {
			httpx.SendJSONError(w, "One speed test every 2 minutes, please wait", http.StatusTooManyRequests)
			return
		}
	}

	provider, err := backupstorage.Open(r.Context(), bs, h.backupDeps())
	if err != nil {
		httpx.SendJSONError(w, err.Error(), http.StatusBadRequest)
		return
	}
	var suffix [8]byte
	_, _ = rand.Read(suffix[:])
	key := "__dylaris_speedtest_" + hex.EncodeToString(suffix[:])
	url, err := provider.UploadURL(r.Context(), key, 10*time.Minute)
	if err != nil {
		httpx.SendJSONError(w, "Could not sign an upload: "+err.Error(), http.StatusBadGateway)
		return
	}
	if url == "" {
		httpx.SendJSONError(w, "The speed test needs object storage (S3); this storage is a directory", http.StatusBadRequest)
		return
	}
	// Whatever happens, the object goes: a test that timed out may still have
	// landed on the storage.
	defer func() {
		ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
		defer cancel()
		if err := provider.Delete(ctx, key); err != nil {
			log.Printf("speed test: storage %d: could not delete %s: %v", bs.ID, key, err)
		}
	}()

	test := &pbNode.StorageSpeedTestReq{Url: url, SizeBytes: req.SizeMB << 20}
	if backupstorage.TenantEndpoint(bs) {
		test.Guarded = true
		test.AllowPrivate = services.PrivateAllowFor(node)
	}
	resp, err := h.d.GRPCRegistry.SendRequest(node.ID, &pbNode.NodeMessage{
		RequestId: uuid.NewString(),
		Payload:   &pbNode.NodeMessage_StorageSpeedTestReq{StorageSpeedTestReq: test},
	}, speedTestWait)
	if err != nil {
		httpx.SendJSONError(w, "The node did not answer: "+err.Error(), http.StatusGatewayTimeout)
		return
	}
	if e := resp.GetError(); e != nil {
		msg := e.Message
		// The guard's refusal names the address the tenant's endpoint resolved
		// to, which would map our network for them.
		if strings.Contains(msg, "not a public address") {
			msg = "This endpoint resolves to a private or internal address. Use your storage provider's public endpoint."
		}
		httpx.SendJSONError(w, msg, http.StatusBadGateway)
		return
	}
	res := resp.GetStorageSpeedTestResp()
	if res == nil || res.DurationMs <= 0 {
		httpx.SendJSONError(w, "The node answered with something else", http.StatusBadGateway)
		return
	}
	name := node.DisplayName
	if name == "" {
		name = node.Name
	}
	json.NewEncoder(w).Encode(map[string]any{
		"success":    true,
		"mbit":       speedTestMbit(res.Bytes, res.DurationMs),
		"bytes":      res.Bytes,
		"durationMs": res.DurationMs,
		"lan":        res.Lan,
		"node":       name,
	})
}

func storageIDParam(r *http.Request) int {
	id, _ := strconv.Atoi(mux.Vars(r)["id"])
	return id
}

// speedTestMbit is bytes over milliseconds in Mbit/s, rounded down.
func speedTestMbit(bytes, ms int64) int64 {
	if ms <= 0 {
		return 0
	}
	return bytes * 8 / 1000 / ms
}
